import { X } from "lucide-react"
import { lazy, Suspense, useCallback, useRef } from "react"

import { Button } from "@/components/atomic/Button"
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerHeader,
  DrawerSwipeHandle,
} from "@/components/atomic/drawer/drawer"
import { Skeleton } from "@/components/atomic/Skeleton"

import type { RepoFileViewerProps } from "./RepoFileViewer"

interface RepoFileViewerDrawerProps extends Omit<RepoFileViewerProps, "active" | "closeButtonRef"> {
  open: boolean
  onOpenChange?: (open: boolean) => void
  finalFocus?: React.RefObject<HTMLElement | null>
}

type LoadedRepoFileViewer = {
  default: (typeof import("./RepoFileViewer"))["RepoFileViewer"]
}

let repoFileViewerPromise: Promise<LoadedRepoFileViewer> | undefined

function loadRepoFileViewer(): Promise<LoadedRepoFileViewer> {
  repoFileViewerPromise ??= import("./RepoFileViewer")
    .then((module) => ({ default: module.RepoFileViewer }))
    .catch((error: unknown) => {
      repoFileViewerPromise = undefined
      throw error
    })
  return repoFileViewerPromise
}

const LazyRepoFileViewer = lazy(loadRepoFileViewer)

export function preloadRepoFileViewer() {
  if (typeof window === "undefined") return

  void loadRepoFileViewer().catch(() => undefined)
}

function RepoFileViewerDrawerLoading({
  closeButtonRef,
}: {
  closeButtonRef: React.RefObject<HTMLButtonElement | null>
}) {
  return (
    <div
      data-testid="repo-file-viewer-drawer-loading"
      className="flex min-h-0 flex-col bg-(--surface-base)"
    >
      <DrawerHeader className="justify-between">
        <Skeleton className="size-8 rounded-lg" />
        <DrawerClose asChild>
          <Button ref={closeButtonRef} size="icon-small" variant="ghost" aria-label="Close">
            <X size={16} className="text-muted" />
          </Button>
        </DrawerClose>
      </DrawerHeader>
      <div className="grid min-h-0 flex-1 grid-cols-1 lg:grid-cols-[20rem_minmax(0,1fr)]">
        <div className="hidden border-r border-neutral-200 p-3 lg:block dark:border-neutral-800">
          <Skeleton className="mb-3 h-8 w-full" />
          <div className="space-y-2">
            {Array.from({ length: 8 }, (_, index) => (
              <Skeleton key={index} className="h-4 w-full" />
            ))}
          </div>
        </div>
        <div className="min-h-0 p-4">
          <Skeleton className="size-full min-h-40" />
        </div>
      </div>
    </div>
  )
}

export function RepoFileViewerDrawer({
  open,
  onOpenChange,
  finalFocus,
  onClose,
  ...contentProps
}: RepoFileViewerDrawerProps) {
  const closeButtonRef = useRef<HTMLButtonElement | null>(null)

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      onOpenChange?.(nextOpen)
      if (!nextOpen) onClose()
    },
    [onClose, onOpenChange],
  )

  return (
    <Drawer open={open} onOpenChange={handleOpenChange} direction="down">
      <DrawerContent
        aria-label="Code viewer"
        initialFocus={closeButtonRef}
        finalFocus={finalFocus}
        className="flex size-full min-h-0 flex-col"
      >
        <DrawerSwipeHandle />
        <Suspense fallback={<RepoFileViewerDrawerLoading closeButtonRef={closeButtonRef} />}>
          <LazyRepoFileViewer
            {...contentProps}
            active={open}
            onClose={onClose}
            closeButtonRef={closeButtonRef}
          />
        </Suspense>
      </DrawerContent>
    </Drawer>
  )
}

