interface DrawerContextValue {
  direction: DrawerDirection
}

const DrawerContext = createContext<DrawerContextValue | null>(null)

function useDrawerContext() {
  const context = use(DrawerContext)
  if (!context) throw new Error("Drawer components must be used within a Drawer")
  return context
}

export interface DrawerProps {
  children: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: DrawerOpenChangeHandler
  onOpenChangeComplete?: (open: boolean) => void
  direction?: DrawerDirection
}

export function Drawer({
  children,
  open,
  defaultOpen,
  onOpenChange,
  onOpenChangeComplete,
  direction = "down",
}: DrawerProps) {
  const drawerContext = useMemo<DrawerContextValue>(() => ({ direction }), [direction])

  return (
    <DrawerContext value={drawerContext}>
      <ModalRoot
        open={open}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
        onOpenChangeComplete={onOpenChangeComplete}
      >
        {children}
      </ModalRoot>
    </DrawerContext>
  )
}

