interface DrawerSwipeIgnoreProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode
  asChild?: boolean
}

export function DrawerSwipeIgnore({ children, asChild, ...props }: DrawerSwipeIgnoreProps) {
  if (asChild) {
    if (!isValidElement(children)) {
      throw new Error("DrawerSwipeIgnore with asChild requires a single React element child")
    }
    return cloneElement(children as ReactElement<Record<string, unknown>>, {
      ...props,
      "data-drawer-swipe-ignore": "",
    })
  }

  return (
    <div data-drawer-swipe-ignore="" {...props}>
      {children}
    </div>
  )
}

