import { clsx } from "clsx"
import { PanelLeftClose, PanelLeftOpen } from "lucide-react"
import { type KeyboardEventHandler, type ReactNode, type Ref } from "react"

import { Button } from "@/components/atomic/Button"
import { DrawerHeader, DrawerSwipeIgnore } from "@/components/atomic/drawer/drawer"
import { ResizableSplit } from "@/components/atomic/ResizableSplit"
import { useMediaQuery } from "@/hooks/useMediaQuery"
import { usePersistentState } from "@/hooks/usePersistentState"

// Resizable sidebar only applies side-by-side (lg+); below that the layout
// stacks and there's nothing to resize.
const DESKTOP_QUERY = "(min-width: 1024px)"
const SIDEBAR_PANEL_ID = "file-tree"
const MAIN_PANEL_ID = "file-viewer-main"
// Sidebar sizes in pixels so the default matches the pre-migration fixed 320px
// column and stays constant across viewport widths (a percentage would balloon
// on wide monitors). The main pane keeps a percentage floor.
const SIDEBAR_DEFAULT_PX = 320
const SIDEBAR_MIN_PX = 260
const SIDEBAR_MAX_PX = 600
const SIDEBAR_COLLAPSE_DISTANCE_PX = 20
const MAIN_MIN_PCT = 40

interface FileViewerShellProps {
  fileTreeOpen: boolean
  onFileTreeOpenChange: (open: boolean) => void
  fileTreeSidebar: ReactNode
  headerLeading?: ReactNode
  headerTrailing?: ReactNode
  children: ReactNode
  rightPanel?: ReactNode
  mainRef?: Ref<HTMLElement>
  className?: string
  headerClassName?: string
  contentClassName?: string
  openGridClassName?: string
  closedGridClassName?: string
  mainClassName?: string
  /** Distinct id so each surface persists its own sidebar width. */
  layoutId?: string
  onKeyDown?: KeyboardEventHandler<HTMLDivElement>
  onKeyDownCapture?: KeyboardEventHandler<HTMLDivElement>
}

/**
 * Shared code/diff viewer chrome: header, file-tree toggle, resizable sidebar,
 * and scrollable main pane. Callers provide the data-specific
 * sidebar and content (raw code, diffs, symbols, etc.).
 */
export function FileViewerShell({
  fileTreeOpen,
  onFileTreeOpenChange,
  fileTreeSidebar,
  headerLeading,
  headerTrailing,
  children,
  rightPanel,
  mainRef,
  className,
  headerClassName,
  contentClassName,
  openGridClassName = "grid grid-cols-[320px_minmax(0,1fr)]",
  closedGridClassName = "grid grid-cols-1",
  mainClassName,
  layoutId = "default",
  onKeyDown,
  onKeyDownCapture,
}: FileViewerShellProps) {
  const isDesktop = useMediaQuery(DESKTOP_QUERY)
  const [sidebarPx, setSidebarPx] = usePersistentState<number>(
    `file-tree-panel-px:${layoutId}`,
    SIDEBAR_DEFAULT_PX,
  )

  const mainContent = (
    <main ref={mainRef} className={clsx("min-h-0 min-w-0", mainClassName ?? "overflow-auto")}>
      {children}
    </main>
  )

  return (
    <div
      className={clsx("flex h-full min-h-0 flex-col bg-(--surface-base)", className)}
      onKeyDown={onKeyDown}
      onKeyDownCapture={onKeyDownCapture}
    >
      <DrawerHeader className={clsx("justify-between", headerClassName)}>
        <div className="flex min-w-0 items-center gap-1">
          <Button
            size="icon-small"
            aria-label={fileTreeOpen ? "Hide file tree" : "Show file tree"}
            aria-pressed={fileTreeOpen}
            onClick={() => onFileTreeOpenChange(!fileTreeOpen)}
            className="shrink-0"
          >
            {fileTreeOpen ? (
              <PanelLeftClose size={16} className="text-muted" />
            ) : (
              <PanelLeftOpen size={16} className="text-muted" />
            )}
          </Button>
          {headerLeading}
        </div>
        {headerTrailing ? (
          <div className="flex shrink-0 items-center gap-1">{headerTrailing}</div>
        ) : null}
      </DrawerHeader>

      <DrawerSwipeIgnore asChild>
        <div className={clsx("relative min-h-0 flex-1", contentClassName)}>
          {isDesktop ? (
            <ResizableSplit.Sidebar.Root
              className="flex size-full min-h-0"
              open={fileTreeOpen}
              onOpenChange={onFileTreeOpenChange}
              size={sidebarPx}
              onSizeChange={setSidebarPx}
              minSize={SIDEBAR_MIN_PX}
              maxSize={SIDEBAR_MAX_PX}
              collapseDistance={SIDEBAR_COLLAPSE_DISTANCE_PX}
            >
              <ResizableSplit.Sidebar.Panel id={SIDEBAR_PANEL_ID}>
                {fileTreeSidebar}
              </ResizableSplit.Sidebar.Panel>
              <ResizableSplit.Sidebar.Handle aria-label="Resize file tree" />
              <ResizableSplit.Panel
                id={MAIN_PANEL_ID}
                className="relative min-h-0 min-w-0"
                minSize={String(MAIN_MIN_PCT)}
                groupResizeBehavior="preserve-relative-size"
              >
                {mainContent}
                {rightPanel}
              </ResizableSplit.Panel>
            </ResizableSplit.Sidebar.Root>
          ) : (
            <div className={clsx("h-full", fileTreeOpen ? openGridClassName : closedGridClassName)}>
              {fileTreeOpen ? fileTreeSidebar : null}
              {mainContent}
              {rightPanel}
            </div>
          )}
        </div>
      </DrawerSwipeIgnore>
    </div>
  )
}

  const symbolsToggle = handleSymbolsOpenChange ? (
    <SymbolsToggle open={effectiveSymbolsOpen} onOpenChange={handleSymbolsOpenChange} />
  ) : null
  const headerActions = ({ previewing }: { previewing: boolean }) =>
    handleSymbolsOpenChange ? (
      <SymbolsToggle
        open={effectiveSymbolsOpen}
        disabled={previewing}
        onOpenChange={handleSymbolsOpenChange}
      />
    ) : null
  const renderSidePanel = effectiveSymbolsOpen
    ? (fileContent: string) => (
        <CodeFileSymbols
          filePath={filePath}
          fileContent={fileContent}
          symbols={symbols}
          highlightedLine={highlightedRange?.start}
          onSymbolClick={handleSymbolClick}
          isLoading={symbolsQuery.isLoading}
          isError={symbolsQuery.isError && !symbolsDenied}
          usagesActive={usagesTarget != null}
          usages={usagesQuery.data}
          isUsagesLoading={
            usagesQuery.isFetching ||
            (usagesTarget != null && !usagesQuery.data && !usagesQuery.isError)
          }
          isUsagesError={!usagesQuery.isFetching && usagesQuery.isError}
          onUsageClick={handleUsageClick}
          onUsagesDismiss={() => setUsagesTarget(null)}
        />
      )
    : undefined

  return (
    <FileViewerShell
      layoutId="code"
      fileTreeOpen={fileTreeOpen}
      onFileTreeOpenChange={setFileTreeOpen}
      fileTreeSidebar={fileTreeSidebar}
      headerTrailing={headerTrailing}
      mainRef={codeScrollRef}
      className="size-full"
      openGridClassName="grid grid-cols-1 lg:grid-cols-[20rem_minmax(0,1fr)]"
      closedGridClassName="grid grid-cols-1"
      mainClassName="size-full overflow-hidden bg-(--surface-base)"
      onKeyDownCapture={handleKeyDownCapture}
    >
      {filePath ? (
        <CodeFileErrorBoundary
          key={`${org}/${repo}/${branch}:${filePath}`}
          fallback={<CodeFileMessage>File not found</CodeFileMessage>}
        >
          <Suspense
            fallback={
              <CodeFileLoadingView
                filePath={filePath}
                fileSize={selectedFileSize}
                actions={symbolsToggle}
                showSidePanel={effectiveSymbolsOpen}
              />
            }
          >
            {isImage ? (
              <ImageFileView
                provider={provider}
                org={org}
                repo={repo}
                branch={branch}
                filePath={filePath}
                fileSize={selectedFileSize}
              />
            ) : (
              <CodeFileContent
                provider={provider}
                org={org}
                repo={repo}
                branch={branch}
                filePath={filePath}
                fileSize={selectedFileSize}
                language={language}
                wrapLines={wrapLines}
                highlightedLine={highlightedRange?.start}
                highlightedLineEnd={highlightedRange?.end}
                initialLine={initialLine}
                onLineClick={handleLineClick}
                onNavigateFile={(path) => onNavigateFile(path)}
                onTokenClick={handleTokenClick}
                hasTokenTarget={hasTokenTarget}
                onSelectedRangePreview={handleSelectedRangePreview}
                onSelectedRangeChange={handleSelectedRangeChange}
                renderSidePanel={renderSidePanel}
                headerActions={headerActions}
              />
            )}
          </Suspense>
        </CodeFileErrorBoundary>
      ) : (
