}: Omit<DiffDrawerProps<TAnnotationMetadata>, "open" | "finalFocus"> & {
  closeButtonRef: RefObject<HTMLButtonElement | null>
}) {
  const [filter, setFilter] = useState("")
  // The tree model captures git status and decorations at construction.
  // Remount only tree owners when commit stats change; the drawer shell and
  // focused header controls must stay mounted.
  const treeKey = fileStats
    .map((file) => `${file.filename}:${file.status}:${file.additions}:${file.deletions}`)
    .join("\n")

  const handleKeyDownCapture = useCallback(
    (event: KeyboardEvent) => {
      if (event.key !== "Escape") return
      if (document.querySelector("[data-floating-overlay]")) return
      event.preventDefault()
      event.stopPropagation()
      onOpenChange(false)
    },
    [onOpenChange],
  )

  const handleDockedTreeKeyDownCapture = useCallback(
    (event: KeyboardEvent) => {
      if (event.key !== "Tab" || event.shiftKey || !selectedFile) return
      const startedOnTreeItem = event.nativeEvent
        .composedPath()
        .some((target) => target instanceof Element && target.getAttribute("role") === "treeitem")
      if (!startedOnTreeItem) return

      const collapseButton = document.getElementById(
        `${DRAWER_FILE_ID_PREFIX}${selectedFile}-trigger`,
      )
      if (!(collapseButton instanceof HTMLButtonElement) || collapseButton.disabled) return

      event.preventDefault()
      event.stopPropagation()
      collapseButton.focus({ preventScroll: true })
    },
    [selectedFile],
  )

  const settings = {
    viewMode,
    wrapLines,
    fileTreeOpen,
    diffIndicators,
    lineDiffType,
    showLineNumbers,
    hunkSeparators,
