      key={treeKey}
      fileStats={fileStats}
      selectedFile={selectedFile}
      onSelectFile={onSelectFile}
      filter={filter}
      onFilterChange={setFilter}
      frame={FILE_TREE_SIDEBAR_FRAME.docked}
      onKeyDownCapture={handleDockedTreeKeyDownCapture}
      isLoading={contentStatus === "loading"}
    />
  )

  const headerTrailing = (
    <>
      <ButtonGroup size="icon-small" aria-label="Diff view mode">
        <Button
          size="icon-small"
          aria-label="Unified diff"
          aria-pressed={viewMode === "unified"}
          onClick={() => onViewModeChange("unified")}
        >
          <Rows3 size={16} className="text-muted" />
        </Button>
        <Button
          size="icon-small"
          aria-label="Split diff"
          aria-pressed={viewMode === "split"}
          onClick={() => onViewModeChange("split")}
        >
          <Columns2 size={16} className="text-muted" />
        </Button>
      </ButtonGroup>
      <Button
        size="icon-small"
        aria-label="Wrap lines"
        aria-pressed={wrapLines}
        onClick={() => onWrapLinesChange(!wrapLines)}
        className={wrapLines ? "bg-hover" : undefined}
      >
        <WrapText size={16} className="text-muted" />
      </Button>
      <DrawerClose asChild>
        <Button ref={closeButtonRef} size="icon-small" variant="ghost" aria-label="Close">
          <X size={16} className="text-muted" />
        </Button>
      </DrawerClose>
    </>
  )

  return (
    <FileViewerShell
      layoutId="diff"
      fileTreeOpen={fileTreeOpen}
      onFileTreeOpenChange={onFileTreeOpenChange}
      fileTreeSidebar={fileTreeSidebar}
      headerLeading={headerLeading}
      headerTrailing={headerTrailing}
      className="size-full"
      openGridClassName="grid grid-cols-1 lg:grid-cols-[20rem_minmax(0,1fr)]"
      closedGridClassName="grid grid-cols-1"
      mainClassName="size-full overflow-hidden bg-(--surface-base)"
      onKeyDownCapture={handleKeyDownCapture}
    >
      <DiffWorkerPoolProvider>
        <DiffDrawerMainContent
          fileStats={fileStats}
          selectedFile={selectedFile}
          getFileLinkOptions={getFileLinkOptions}
          diffViewRef={diffViewRef}
          lineSelection={lineSelection}
          imageSource={imageSource}
          settings={settings}
          targetAnnotationId={targetAnnotationId}
          targetScrollElementId={targetScrollElementId}
          annotations={annotations}
          renderAnnotation={renderAnnotation}
          onCodeLinePointerDown={onCodeLinePointerDown}
          contentStatus={contentStatus}
          contentStatusMessage={contentStatusMessage}
          onRetryContent={onRetryContent}
        />
      </DiffWorkerPoolProvider>
    </FileViewerShell>
  )
}

