import "@testing-library/jest-dom/vitest"
import { fireEvent, render, screen, waitFor } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { useState } from "react"
import { describe, expect, it } from "vitest"

import { useDialogReturnFocus } from "@/hooks/useDialogReturnFocus"

import { Button } from "../Button"
import { Drawer, DrawerClose, DrawerContent, DrawerHeader, DrawerSwipeHandle } from "./drawer"

function BottomDrawerHarness() {
  const [open, setOpen] = useState(false)
  const { defaultReturnFocusRef, returnFocusRef, captureReturnFocus } =
    useDialogReturnFocus<HTMLButtonElement>({ open })

  const openFrom = (trigger?: HTMLElement) => {
    captureReturnFocus(trigger)
    setOpen(true)
  }

  return (
    <>
      <button
        ref={defaultReturnFocusRef}
        type="button"
        onClick={(event) => openFrom(event.currentTarget)}
      >
        Open drawer
      </button>
      <button type="button" onClick={(event) => openFrom(event.currentTarget)}>
        Finding location
      </button>
      <button
        type="button"
        onKeyDown={(event) => {
          if (event.key !== "d") return
          openFrom()
        }}
      >
        Shortcut context
      </button>
      <output data-testid="drawer-state">{open ? "open" : "closed"}</output>
      <Drawer open={open} onOpenChange={setOpen}>
        <DrawerContent aria-label="Test drawer" finalFocus={returnFocusRef}>
          <DrawerSwipeHandle />
          <DrawerHeader>
            <DrawerClose asChild>
              <Button size="icon-small" variant="ghost" aria-label="Close drawer">
                Close drawer
              </Button>
            </DrawerClose>
          </DrawerHeader>
        </DrawerContent>
      </Drawer>
    </>
  )
}

function NestedDrawerHarness() {
  const [childOpen, setChildOpen] = useState(true)

  return (
    <Drawer open>
      <DrawerContent aria-label="Parent drawer">
        <DrawerHeader>
          <button type="button" onClick={() => setChildOpen(true)}>
            Open child drawer
          </button>
        </DrawerHeader>
        <Drawer open={childOpen} onOpenChange={setChildOpen}>
          <DrawerContent aria-label="Child drawer">
            <DrawerSwipeHandle />
            <DrawerHeader />
          </DrawerContent>
        </Drawer>
      </DrawerContent>
    </Drawer>
  )
}

describe("Drawer", () => {
  it("can dismiss by swipe when it reopens during the close transition", async () => {
    render(<BottomDrawerHarness />)

    const openButton = screen.getByRole("button", { name: "Open drawer" })
    fireEvent.click(openButton)
    dismissDrawerWithMouseSwipe()
    expect(screen.getByTestId("drawer-state")).toHaveTextContent("closed")

    fireEvent.click(openButton)
    dismissDrawerWithMouseSwipe()
    expect(screen.getByTestId("drawer-state")).toHaveTextContent("closed")
  })

  it("can dismiss a nested drawer by swipe after it reopens", async () => {
    const user = userEvent.setup()
    render(<NestedDrawerHarness />)

    dismissDrawerWithMouseSwipe("Child drawer")
    await waitFor(() => expect(screen.queryByRole("dialog", { name: "Child drawer" })).toBeNull())

    await user.click(screen.getByRole("button", { name: "Open child drawer" }))
    dismissDrawerWithMouseSwipe("Child drawer")
    await waitFor(() => expect(screen.queryByRole("dialog", { name: "Child drawer" })).toBeNull())
  })

  it("returns focus to the button that opened it", async () => {
    const user = userEvent.setup()
    render(<BottomDrawerHarness />)
    const openButton = screen.getByRole("button", { name: "Open drawer" })

    await user.click(openButton)
    await user.click(screen.getByRole("button", { name: "Close drawer" }))

    await waitFor(() => expect(openButton).toHaveFocus())
  })

  it("returns focus to a secondary opener", async () => {
    const user = userEvent.setup()
    render(<BottomDrawerHarness />)
    const findingButton = screen.getByRole("button", { name: "Finding location" })

    await user.click(findingButton)
    await user.click(screen.getByRole("button", { name: "Close drawer" }))

    await waitFor(() => expect(findingButton).toHaveFocus())
  })

  it("returns focus to the element focused before a shortcut", async () => {
    const user = userEvent.setup()
    render(<BottomDrawerHarness />)
    const contextButton = screen.getByRole("button", { name: "Shortcut context" })

    await user.click(contextButton)
    await user.keyboard("d")
    await user.click(screen.getByRole("button", { name: "Close drawer" }))

    await waitFor(() => expect(contextButton).toHaveFocus())
  })
})

function dismissDrawerWithMouseSwipe(label = "Test drawer") {
  const drawer = screen.getByRole("dialog", { name: label })
  const header = drawer.querySelector<HTMLElement>('[data-slot="drawer-header"]')
  if (!header) throw new Error("Drawer header is required")
  drawer.setPointerCapture = () => undefined

  fireEvent.pointerDown(header, {
    button: 0,
    clientX: 0,
    clientY: 0,
    pointerId: 1,
    pointerType: "mouse",
  })
  fireEvent.pointerMove(header, {
    clientX: 0,
    clientY: 40,
    pointerId: 1,
    pointerType: "mouse",
  })
  fireEvent.pointerUp(header, {
    clientX: 0,
    clientY: 40,
    pointerId: 1,
    pointerType: "mouse",
  })
}

