/**
 * Entire Trails Extension
 *
 * Shows a clickable trail link in the Pi footer for the current git branch.
 * Resolves the trail through Entire's API, then watches the trail-scoped
 * trail-wide event SSE stream:
 *
 *   GET /api/v1/trails/:host/:owner/:repo/:number/events
 *   Accept: text/event-stream
 *
 * New live review comments are fetched and injected into the active Pi session
 * as user messages.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFileSync, execSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

interface TrailInfo {
	id: string;
	number: number;
	title?: string;
	branch: string;
	url: string;
	eventsPath: string;
}

interface EntireAuth {
	baseUrl: string;
	token: string;
}

interface EntireLoginContext {
	name?: string;
	core_url?: string;
	handle?: string;
	keychain_service?: string;
}

interface EntireContextsFile {
	current_context?: string;
	contexts?: EntireLoginContext[];
}

interface StoredToken {
	token: string;
	expiresAt?: number;
}

interface OAuthTokenResponse {
	access_token?: string;
	refresh_token?: string;
	expires_in?: number;
	error?: unknown;
	error_description?: unknown;
}

interface APIDiscoveryResponse {
	trusted_issuers?: unknown;
}

interface TrailResource {
	id?: string;
	trail_id?: string;
	number?: number;
	branch?: string;
	// Backward/forward-compatible with trail create/update payloads.
	branch_name?: string;
	title?: string;
}

interface TrailListResponse {
	trails?: TrailResource[];
	total?: number;
	limit?: number;
	offset?: number;
}

interface RepositoryListResponse {
	repositories?: Array<{ full_name?: string; name?: string }>;
}

interface CodeReviewEvent {
	id?: string;
	trail_id?: string;
	review_id?: string | null;
	// Backward-compatible with older event payloads.
	review_session_id?: string | null;
	actor_id?: string;
	event_type?: string;
	target_type?: string;
	target_id?: string;
	payload?: Record<string, unknown> | null;
	created_at?: string;
}

interface ReviewComment {
	id: string;
	actor_id?: string;
	title?: string | null;
	body?: string | null;
	severity?: string | null;
	review_id?: string | null;
	// Backward-compatible with older comment payloads.
	review_session_id?: string | null;
	location?: {
		file_path?: string | null;
		start_line?: number | null;
		end_line?: number | null;
		selected_text?: string | null;
	};
}

interface SSEFrame {
	event: string;
	id?: string;
	data?: unknown;
}

type TrailLookup =
	| { status: "none" }
	| { status: "no-trail"; branch: string }
	| { status: "error"; message: string }
	| { status: "found"; trail: TrailInfo };

type ExtensionCtx = {
	cwd: string;
	ui: {
		notify: (message: string, level?: string) => void;
		setStatus: (id: string, text: string | undefined) => void;
		theme: { fg: (color: string, text: string) => string };
	};
};

const DEFAULT_API_BASE_URL = "https://entire.io";
const DEFAULT_AUTH_BASE_URL = "https://us.auth.entire.io";
const ENTIRE_CLIENT_ID = "entire-cli";
const TOKEN_EXCHANGE_GRANT = "urn:ietf:params:oauth:grant-type:token-exchange";
const ACCESS_TOKEN_TYPE = "urn:ietf:params:oauth:token-type:access_token";
const TOKEN_EXPIRY_SKEW_MS = 30_000;
const DEFAULT_REFRESHED_TOKEN_TTL_SECONDS = 60 * 60;

function normalizeOriginUrl(raw: string): string {
	const trimmed = raw.trim();
	try {
		const parsed = new URL(trimmed);
		const scheme = parsed.protocol.toLowerCase();
		const hostname = parsed.hostname.replace(/^\[|\]$/g, "").toLowerCase();
		const dropPort = !parsed.port || (scheme === "https:" && parsed.port === "443") || (scheme === "http:" && parsed.port === "80");
		const host = hostname.includes(":") ? `[${hostname}]${dropPort ? "" : `:${parsed.port}`}` : `${hostname}${dropPort ? "" : `:${parsed.port}`}`;
		return `${scheme}//${host}`;
	} catch {
		return trimmed.replace(/\/+$/, "");
	}
}

function normalizeBaseUrl(raw: string | undefined): string {
	return (raw?.trim() || DEFAULT_API_BASE_URL).replace(/\/+$/, "");
}

function normalizeAuthBaseUrl(raw: string | undefined): string {
	return normalizeOriginUrl(raw?.trim() || DEFAULT_AUTH_BASE_URL);
}

function configDir(): string {
	return process.env.ENTIRE_CONFIG_DIR || path.join(os.homedir(), ".config", "entire");
}

function tokenStorePath(): string {
	return process.env.ENTIRE_TOKEN_STORE_PATH || path.join(configDir(), "tokens.json");
}

function decodeStoredToken(raw: string): string {
	const token = raw.trim();
	const prefix = "go-keyring-base64:";
	if (!token.startsWith(prefix)) return token;
	try {
		return Buffer.from(token.slice(prefix.length), "base64").toString("utf8").trim();
	} catch {
		return token;
	}
}

function decodeTokenWithExpiration(raw: string): StoredToken {
	const decoded = decodeStoredToken(raw);
	const idx = decoded.lastIndexOf("|");
	if (idx < 0) return { token: decoded.trim() };

	const suffix = decoded.slice(idx + 1).trim();
	if (!/^\d+$/.test(suffix)) return { token: decoded.trim() };
	return { token: decoded.slice(0, idx).trim(), expiresAt: Number(suffix) * 1000 };
}

function readFileToken(service: string, account: string): string | null {
	try {
		const raw = fs.readFileSync(tokenStorePath(), "utf8");
		const store = JSON.parse(raw) as unknown;
		if (!isObject(store)) return null;
		const serviceEntry = store[service];
		if (!isObject(serviceEntry)) return null;
		const value = serviceEntry[account];
		return typeof value === "string" && value.trim() ? decodeStoredToken(value) : null;
	} catch {
		return null;
	}
}

function writeFileToken(service: string, account: string, value: string): void {
	const file = tokenStorePath();
	fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
	let store: Record<string, Record<string, string>> = {};
	try {
		const raw = fs.readFileSync(file, "utf8");
		if (raw.trim()) {
			const parsed = JSON.parse(raw) as unknown;
			if (!isObject(parsed)) throw new Error("token store is not an object");
			store = parsed as Record<string, Record<string, string>>;
		}
	} catch (err) {
		if ((err as { code?: string }).code !== "ENOENT") throw err;
	}
	if (!isObject(store[service])) store[service] = {};
	store[service]![account] = value;

	const tmp = path.join(path.dirname(file), `.tokens-${process.pid}-${Date.now()}.tmp`);
	fs.writeFileSync(tmp, JSON.stringify(store), { mode: 0o600 });
	fs.renameSync(tmp, file);
}

function readKeychainToken(service: string, account: string): string | null {
	if (process.platform !== "darwin") return null;
	try {
		const stored = execFileSync("security", ["find-generic-password", "-s", service, "-a", account, "-w"], {
			encoding: "utf8",
			timeout: 5000,
		});
		const token = decodeStoredToken(stored);
		return token.trim() || null;
	} catch {
		return null;
	}
}

function writeKeychainToken(service: string, account: string, value: string): void {
	if (process.platform !== "darwin") throw new Error("OS keychain access is only implemented for macOS");
	execFileSync("security", ["add-generic-password", "-U", "-s", service, "-a", account, "-w", value], {
		stdio: "ignore",
		timeout: 5000,
	});
}

function readStoredToken(service: string, account: string): string | null {
	return process.env.ENTIRE_TOKEN_STORE === "file" ? readFileToken(service, account) : readKeychainToken(service, account);
}

function writeStoredToken(service: string, account: string, value: string): void {
	if (process.env.ENTIRE_TOKEN_STORE === "file") writeFileToken(service, account, value);
	else writeKeychainToken(service, account, value);
}

function jwtClaims(token: string): Record<string, unknown> | null {
	const [, payload] = token.split(".");
	if (!payload) return null;
	try {
		const normalized = payload.replace(/-/g, "+").replace(/_/g, "/");
		const padded = normalized + "=".repeat((4 - (normalized.length % 4)) % 4);
		const parsed = JSON.parse(Buffer.from(padded, "base64").toString("utf8")) as unknown;
		return isObject(parsed) ? parsed : null;
	} catch {
		return null;
	}
}

function jwtExpirationMs(token: string): number | undefined {
	const exp = jwtClaims(token)?.exp;
	return typeof exp === "number" && Number.isFinite(exp) ? exp * 1000 : undefined;
}

function tokenExpiredOrExpiring(token: string, fallbackExpiresAt?: number): boolean {
	const expiresAt = jwtExpirationMs(token) ?? fallbackExpiresAt;
	return expiresAt ? Date.now() + TOKEN_EXPIRY_SKEW_MS >= expiresAt : false;
}

function jwtAudienceIncludes(token: string, targetOrigin: string): boolean {
	const audience = jwtClaims(token)?.aud;
	const values = Array.isArray(audience) ? audience : typeof audience === "string" ? [audience] : [];
	return values.some((value) => typeof value === "string" && normalizeOriginUrl(value) === targetOrigin);
}

function authProvider(): { clientID: string; tokenPath: string; stsPath: string } {
	const requested = process.env.ENTIRE_AUTH_PROVIDER_VERSION?.trim();
	const splitHost = normalizeAuthBaseUrl(process.env.ENTIRE_AUTH_BASE_URL) !== normalizeOriginUrl(normalizeBaseUrl(process.env.ENTIRE_API_BASE_URL));
	if (requested === "v2" || (!requested && splitHost)) return { clientID: ENTIRE_CLIENT_ID, tokenPath: "/oauth/token", stsPath: "/oauth/token" };
	return { clientID: ENTIRE_CLIENT_ID, tokenPath: "/oauth/token", stsPath: "" };
}

function loadContextsFile(): EntireContextsFile | null {
	try {
		const parsed = JSON.parse(fs.readFileSync(path.join(configDir(), "contexts.json"), "utf8")) as unknown;
		return isObject(parsed) ? (parsed as EntireContextsFile) : null;
	} catch {
		return null;
	}
}

function contextList(file: EntireContextsFile | null): EntireLoginContext[] {
	return (file?.contexts ?? []).filter(
		(c) => !!c && typeof c.core_url === "string" && typeof c.handle === "string" && typeof c.keychain_service === "string",
	);
}

async function discoverTrustedIssuers(dataBaseUrl: string): Promise<string[] | null> {
	const origin = normalizeOriginUrl(dataBaseUrl);
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), 8000);
	try {
		const response = await fetch(`${origin}/.well-known/entire-api.json`, {
			headers: { Accept: "application/json" },
			signal: controller.signal,
		});
		if (!response.ok) return null;
		const json = (await response.json()) as APIDiscoveryResponse;
		const issuers = Array.isArray(json.trusted_issuers) ? json.trusted_issuers : [];
		const normalized = issuers.filter((issuer): issuer is string => typeof issuer === "string" && issuer.trim() !== "").map(normalizeOriginUrl);
		return normalized.length > 0 ? normalized : null;
	} catch {
		return null;
	} finally {
		clearTimeout(timer);
	}
}

async function selectContextForAPI(dataBaseUrl: string): Promise<EntireLoginContext | null> {
	const file = loadContextsFile();
	const contexts = contextList(file);
	if (contexts.length === 0) return null;

	const active = contexts.find((c) => c.name === file?.current_context) ?? null;
	const trustedIssuers = await discoverTrustedIssuers(dataBaseUrl);
	if (!trustedIssuers) return active;

	const trusted = new Set(trustedIssuers);
	const eligible = contexts.filter((c) => trusted.has(normalizeOriginUrl(c.core_url!)));
	if (active && eligible.some((c) => c.name === active.name)) return active;
	if (eligible.length === 1) return eligible[0]!;
	if (eligible.length > 1) {
		const names = eligible.map((c) => c.name || c.core_url).sort().join(", ");
		throw new Error(`Multiple Entire login contexts can authenticate against ${new URL(dataBaseUrl).host} (${names}); run "entire auth use <context>"`);
	}
	throw new Error(`No Entire login context can authenticate against ${new URL(dataBaseUrl).host}; run "entire login"`);
}

async function postOAuthForm(coreUrl: string, endpointPath: string, form: URLSearchParams, clientID: string): Promise<OAuthTokenResponse> {
	const response = await fetch(`${normalizeOriginUrl(coreUrl)}${endpointPath.startsWith("/") ? endpointPath : `/${endpointPath}`}`, {
		method: "POST",
		headers: {
			Accept: "application/json",
			"Content-Type": "application/x-www-form-urlencoded",
			"User-Agent": ENTIRE_CLIENT_ID,
			Authorization: `Basic ${Buffer.from(`${encodeURIComponent(clientID)}:`).toString("base64")}`,
		},
		body: form,
	});
	if (!response.ok) throw new Error(await responseError(response));
	return (await response.json()) as OAuthTokenResponse;
}

async function refreshContextLoginToken(context: EntireLoginContext): Promise<string> {
	const service = context.keychain_service!;
	const handle = context.handle!;
	const refreshService = `${service}:refresh`;
	const refreshToken = readStoredToken(refreshService, handle);
	if (!refreshToken) throw new Error(`Login session for "${context.name || handle}" expired; run "entire login"`);

	const provider = authProvider();
	const form = new URLSearchParams({
		client_id: provider.clientID,
		grant_type: "refresh_token",
		refresh_token: refreshToken,
	});
	let refreshed: OAuthTokenResponse;
	try {
		refreshed = await postOAuthForm(context.core_url!, provider.tokenPath, form, provider.clientID);
	} catch (err) {
		const message = ((err as Error).message || "refresh failed").split("\n")[0] ?? "refresh failed";
		throw new Error(`Login session for "${context.name || handle}" could not be refreshed; run "entire login" (${message})`);
	}
	const accessToken = typeof refreshed.access_token === "string" ? refreshed.access_token.trim() : "";
	if (!accessToken) throw new Error("Refresh response did not include an access token");

	const nextRefreshToken = typeof refreshed.refresh_token === "string" ? refreshed.refresh_token.trim() : "";
	if (nextRefreshToken) writeStoredToken(refreshService, handle, nextRefreshToken);

	const jwtExpiresAt = jwtExpirationMs(accessToken);
	const expiresIn =
		typeof refreshed.expires_in === "number" && refreshed.expires_in > 0
			? refreshed.expires_in
			: jwtExpiresAt && jwtExpiresAt > Date.now()
				? Math.floor((jwtExpiresAt - Date.now()) / 1000)
				: DEFAULT_REFRESHED_TOKEN_TTL_SECONDS;
	writeStoredToken(service, handle, `${accessToken}|${Math.floor(Date.now() / 1000) + expiresIn}`);
	return accessToken;
}

async function loginTokenForContext(context: EntireLoginContext): Promise<string> {
	const stored = readStoredToken(context.keychain_service!, context.handle!);
	if (!stored) throw new Error(`No token stored for "${context.name || context.handle}"; run "entire login"`);
	const decoded = decodeTokenWithExpiration(stored);
	const { token } = decoded;
	if (!token) throw new Error(`No token stored for "${context.name || context.handle}"; run "entire login"`);
	return tokenExpiredOrExpiring(token, decoded.expiresAt) ? refreshContextLoginToken(context) : token;
}

async function dataAPITokenFromLogin(coreUrl: string, loginToken: string, dataBaseUrl: string): Promise<string> {
	const issuer = normalizeOriginUrl(coreUrl);
	const resource = normalizeOriginUrl(dataBaseUrl);
	if (issuer === resource || jwtAudienceIncludes(loginToken, resource)) return loginToken;

	const provider = authProvider();
	if (!provider.stsPath) throw new Error(`Token exchange is required for ${resource}; run "entire login" with the current CLI`);

	const form = new URLSearchParams({
		client_id: provider.clientID,
		grant_type: TOKEN_EXCHANGE_GRANT,
		subject_token: loginToken,
		subject_token_type: ACCESS_TOKEN_TYPE,
		requested_token_type: ACCESS_TOKEN_TYPE,
		audience: resource,
		resource,
	});
	const exchanged = await postOAuthForm(issuer, provider.stsPath, form, provider.clientID);
	const accessToken = typeof exchanged.access_token === "string" ? exchanged.access_token.trim() : "";
	if (!accessToken) throw new Error("Token exchange response did not include an access token");
	return accessToken;
}

function looksJSONShaped(raw: string): boolean {
	const trimmed = raw.trimStart();
	return trimmed.startsWith("{") || trimmed.startsWith("[");
}

async function getContextAuth(baseUrl: string): Promise<EntireAuth | null> {
	const context = await selectContextForAPI(baseUrl);
	if (!context) return null;
	const loginToken = await loginTokenForContext(context);
	return { baseUrl, token: await dataAPITokenFromLogin(context.core_url!, loginToken, baseUrl) };
}

async function getLegacyAuth(baseUrl: string): Promise<EntireAuth | null> {
	const candidates = [normalizeAuthBaseUrl(process.env.ENTIRE_AUTH_BASE_URL), baseUrl];
	let lastError: Error | undefined;
	for (const account of [...new Set(candidates)]) {
		const stored = readStoredToken("entire-cli", account);
		if (!stored || looksJSONShaped(stored)) continue;
		const decoded = decodeTokenWithExpiration(stored);
		const { token } = decoded;
		if (!token || tokenExpiredOrExpiring(token, decoded.expiresAt)) continue;
		try {
			return { baseUrl, token: account === baseUrl ? token : await dataAPITokenFromLogin(account, token, baseUrl) };
		} catch (err) {
			lastError = err as Error;
		}
	}
	if (lastError) throw lastError;
	return null;
}

async function getEntireAuth(): Promise<EntireAuth | null> {
	const baseUrl = normalizeBaseUrl(process.env.ENTIRE_API_BASE_URL);
	const envToken = (process.env.ENTIRE_API_TOKEN || process.env.ENTIRE_TOKEN)?.trim();

	let contextError: Error | undefined;
	try {
		const contextAuth = await getContextAuth(baseUrl);
		if (contextAuth) return contextAuth;
	} catch (err) {
		contextError = err as Error;
	}

	try {
		const legacyAuth = await getLegacyAuth(baseUrl);
		if (legacyAuth) return legacyAuth;
	} catch (err) {
		if (!contextError) contextError = err as Error;
	}

	// Environment tokens are useful for CI, but after the CLI refresh-token
	// migration a stale ENTIRE_TOKEN/ENTIRE_API_TOKEN in Pi's environment should
	// not override the refreshable CLI login and keep the footer stuck on
	// "Token expired".
	if (envToken && !tokenExpiredOrExpiring(envToken)) return { baseUrl, token: envToken };

	if (contextError) throw contextError;
	return null;
}

function apiURL(auth: EntireAuth, path: string): string {
	return `${auth.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
}

async function responseError(response: Response): Promise<string> {
	let text = "";
	try {
		text = await response.text();
	} catch {
		// Ignore; fall through to status text.
	}
	try {
		const parsed = JSON.parse(text) as { error?: unknown; error_description?: unknown };
		if (typeof parsed.error === "string" && parsed.error.trim()) {
			const description = typeof parsed.error_description === "string" && parsed.error_description.trim() ? `: ${parsed.error_description.trim()}` : "";
			return `${parsed.error.trim()}${description}`;
		}
		if (parsed.error && typeof parsed.error === "object") {
			const message = (parsed.error as { message?: unknown }).message;
			if (typeof message === "string" && message.trim()) return message.trim();
		}
	} catch {
		// Not JSON.
	}
	return text.trim() || response.statusText || `HTTP ${response.status}`;
}

async function fetchJSON<T>(auth: EntireAuth, path: string, signal?: AbortSignal): Promise<T> {
	const response = await fetch(apiURL(auth, path), {
		headers: {
			Accept: "application/json",
			Authorization: `Bearer ${auth.token}`,
		},
		signal,
	});
	if (!response.ok) throw new Error(await responseError(response));
	return (await response.json()) as T;
}

function getGitRemote(cwd: string): { org: string; repo: string } | null {
	try {
		const remote = execSync("git remote get-url origin", { cwd, encoding: "utf-8" }).trim();

		const entireMatch = remote.match(/^entire:\/\/[^/]+\/gh\/([^/]+)\/([^/?#]+?)(?:\.git)?(?:[?#].*)?$/);
		if (entireMatch) return { org: decodeURIComponent(entireMatch[1]!), repo: decodeURIComponent(entireMatch[2]!) };

		const githubMatch = remote.match(/github\.com[/:]([^/]+)\/(.+?)(?:\.git)?$/);
		return githubMatch ? { org: githubMatch[1]!, repo: githubMatch[2]! } : null;
	} catch {
		return null;
	}
}

function getGitBranch(cwd: string): string | null {
	try {
		return execSync("git branch --show-current", { cwd, encoding: "utf-8" }).trim() || null;
	} catch {
		return null;
	}
}

function trailURL(remote: { org: string; repo: string }, trail: { number: number; title?: string }, branch: string): string {
	const slug = (trail.title || branch)
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 60);
	return `https://entire.io/gh/${remote.org}/${remote.repo}/trails/${trail.number}${slug ? `/${slug}` : ""}`;
}

function trailEventsPath(remote: { org: string; repo: string }, trailNumber: number): string {
	return `/api/v1/trails/gh/${encodeURIComponent(remote.org)}/${encodeURIComponent(remote.repo)}/${trailNumber}/events`;
}

const TRAIL_LIST_PAGE_LIMIT = 200;

function trailBranch(trail: TrailResource): string {
	return trail.branch ?? trail.branch_name ?? "";
}

function trailListPagePath(basePath: string, branch: string, offset: number): string {
	const params = new URLSearchParams({
		limit: String(TRAIL_LIST_PAGE_LIMIT),
		offset: String(offset),
		search: branch,
	});
	return `${basePath}?${params.toString()}`;
}

async function findTrailForBranch(auth: EntireAuth, basePath: string, branch: string): Promise<TrailResource | undefined> {
	let offset = 0;
	for (let i = 0; i < 100; i++) {
		const page = await fetchJSON<TrailListResponse>(auth, trailListPagePath(basePath, branch, offset));
		const trails = page.trails ?? [];
		const trail = trails.find((t) => trailBranch(t) === branch);
		if (trail) return trail;
		if (trails.length === 0) return undefined;

		const limit = typeof page.limit === "number" && page.limit > 0 ? page.limit : TRAIL_LIST_PAGE_LIMIT;
		const pageOffset = typeof page.offset === "number" && page.offset >= 0 ? page.offset : offset;
		const nextOffset = pageOffset + limit;
		if (nextOffset <= offset) return undefined;
		offset = nextOffset;
		if (typeof page.total === "number" && offset >= page.total) return undefined;
		if (trails.length < limit) return undefined;
	}
	return undefined;
}

async function repositoryVisibleToEntire(auth: EntireAuth, remote: { org: string; repo: string }): Promise<boolean | undefined> {
	try {
		const page = await fetchJSON<RepositoryListResponse>(auth, "/api/v1/repositories");
		const want = `${remote.org}/${remote.repo}`.toLowerCase();
		return (page.repositories ?? []).some((repo) => repo.full_name?.toLowerCase() === want);
	} catch {
		return undefined;
	}
}

async function getTrailForBranch(cwd: string): Promise<TrailLookup> {
	const branch = getGitBranch(cwd);
	const remote = getGitRemote(cwd);
	if (!branch || !remote) return { status: "none" };

	let auth: EntireAuth | null;
	try {
		auth = await getEntireAuth();
	} catch (err) {
		const message = ((err as Error).message || "error").trim().split("\n")[0] ?? "error";
		return { status: "error", message };
	}
	if (!auth) return { status: "error", message: 'Authentication via "entire auth login" required' };

	try {
		const path = `/api/v1/trails/gh/${encodeURIComponent(remote.org)}/${encodeURIComponent(remote.repo)}`;
		const trail = await findTrailForBranch(auth, path, branch);
		if (!trail?.number) return { status: "no-trail", branch };

		const id = trail.id || trail.trail_id;
		if (!id) return { status: "error", message: `Trail #${trail.number} is missing id` };

		return {
			status: "found",
			trail: {
				id,
				number: trail.number,
				title: trail.title?.trim() ? trail.title : undefined,
				branch,
				url: trailURL(remote, { number: trail.number, title: trail.title }, branch),
				eventsPath: trailEventsPath(remote, trail.number),
			},
		};
	} catch (err) {
		const message = ((err as Error).message || "error").trim().split("\n")[0] ?? "error";
		if (/^repository not found$/i.test(message)) {
			const visible = await repositoryVisibleToEntire(auth, remote);
			const name = `${remote.org}/${remote.repo}`;
			if (visible === true) return { status: "error", message: `Trails are not enabled for ${name}.` };
			if (visible === false) return { status: "error", message: `Repository ${name} was not found in Entire.` };
			return { status: "error", message: `Repository ${name}: ${message}` };
		}
		return { status: "error", message };
	}
}

function payloadString(payload: Record<string, unknown> | null | undefined, key: string): string {
	const value = payload?.[key];
	return typeof value === "string" ? value : "";
}

function payloadNumber(payload: Record<string, unknown> | null | undefined, key: string): number | null {
	const value = payload?.[key];
	return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function fencedText(label: string, text: string): string[] {
	return text.trim() ? [label, "```", text.trim(), "```"] : [];
}

function formatReviewComment(trail: TrailInfo, event: CodeReviewEvent, comment?: ReviewComment): string {
	const payload = event.payload ?? null;
	const commentId = comment?.id || event.target_id || "unknown";
	const body = (comment?.body || payloadString(payload, "body")).trim();
	const file = comment?.location?.file_path || payloadString(payload, "file_path");
	const severity = comment?.severity || payloadString(payload, "severity");
	const startLine = comment?.location?.start_line ?? payloadNumber(payload, "start_line");
	const endLine = comment?.location?.end_line ?? payloadNumber(payload, "end_line");
	const selectedText = (comment?.location?.selected_text || payloadString(payload, "selected_text")).trim();
	const location = file
		? `${file}${startLine ? `:${startLine}${endLine && endLine !== startLine ? `-${endLine}` : ""}` : ""}`
		: "";

	return [
		"Entire Trail review comment",
		`ID: ${commentId}`,
		`URL: ${trail.url}`,
		severity ? `Severity: ${severity}` : "",
		location ? `Context: ${location}` : "",
		...fencedText("Selected context:", selectedText),
		body,
	]
		.filter(Boolean)
		.join("\n");
}

function formatTrailLookupError(message: string): string {
	if (/github token expired/i.test(message)) return message;
	return /auth|login|unauthorized|forbidden|not authenticated|invalid_(grant|token)|^token expired\b/i.test(message)
		? 'Authentication via "entire auth login" required'
		: message;
}

function trailLookupMessage(result: Exclude<TrailLookup, { status: "found" }>): string {
	if (result.status === "no-trail") return `No trail found for branch ${result.branch}.`;
	if (result.status === "error") return formatTrailLookupError(result.message);
	return "Cannot resolve current branch/repo trail.";
}

async function latestEventCursor(auth: EntireAuth, eventsPath: string, signal: AbortSignal): Promise<string> {
	let after = "0";
	for (let i = 0; i < 100; i++) {
		const page = await fetchJSON<{ events?: CodeReviewEvent[] }>(
			auth,
			`${eventsPath}?after=${encodeURIComponent(after)}&limit=1000`,
			signal,
		);
		const events = page.events ?? [];
		if (events.length === 0) return after === "0" ? "" : after;
		const last = events[events.length - 1];
		if (!last?.id) return after === "0" ? "" : after;
		after = last.id;
		if (events.length < 1000) return after;
	}
	return after === "0" ? "" : after;
}

async function fetchReviewComment(
	auth: EntireAuth,
	trailId: string,
	reviewId: string,
	commentId: string,
	signal: AbortSignal,
): Promise<ReviewComment | undefined> {
	try {
		return await fetchJSON<ReviewComment>(
			auth,
			`/api/v1/trails/${encodeURIComponent(trailId)}/reviews/${encodeURIComponent(reviewId)}/comments/${encodeURIComponent(commentId)}`,
			signal,
		);
	} catch {
		return undefined;
	}
}

function isObject(value: unknown): value is Record<string, unknown> {
	return !!value && typeof value === "object" && !Array.isArray(value);
}

async function readSSE(
	response: Response,
	signal: AbortSignal,
	onFrame: (frame: SSEFrame) => Promise<void>,
): Promise<"reconnect" | "forbidden" | "error" | "eof" | "done"> {
	const reader = response.body?.getReader();
	if (!reader) return "eof";

	const decoder = new TextDecoder();
	let pending = "";
	let eventName = "";
	let eventId = "";
	let dataLines: string[] = [];

	const dispatch = async (): Promise<"continue" | "reconnect" | "forbidden" | "error"> => {
		if (!eventName && !eventId && dataLines.length === 0) return "continue";
		const name = eventName || "message";
		const id = eventId || undefined;
		const rawData = dataLines.join("\n");
		eventName = "";
		eventId = "";
		dataLines = [];

		let data: unknown = rawData;
		if (rawData) {
			try {
				data = JSON.parse(rawData);
			} catch {
				// Keep raw string.
			}
		}

		await onFrame({ event: name, id, data });
		if (name === "reconnect") return "reconnect";
		if (name === "forbidden") return "forbidden";
		if (name === "error") return "error";
		return "continue";
	};

	while (!signal.aborted) {
		const { done, value } = await reader.read();
		if (done) break;
		pending += decoder.decode(value, { stream: true });

		for (;;) {
			const nl = pending.search(/\r?\n/);
			if (nl < 0) break;
			const line = pending.slice(0, nl).replace(/\r$/, "");
			pending = pending.slice(line.length + (pending[line.length] === "\r" ? 2 : 1));

			if (line === "") {
				const reason = await dispatch();
				if (reason !== "continue") return reason;
				continue;
			}
			if (line.startsWith(":")) continue;

			const colon = line.indexOf(":");
			const field = colon >= 0 ? line.slice(0, colon) : line;
			const value = colon >= 0 ? line.slice(colon + 1).replace(/^ /, "") : "";
			if (field === "event") eventName = value;
			else if (field === "id") eventId = value;
			else if (field === "data") dataLines.push(value);
		}
	}

	if (signal.aborted) return "done";
	const reason = await dispatch();
	return reason === "continue" ? "eof" : reason;
}

function sleep(ms: number, signal: AbortSignal): Promise<void> {
	return new Promise((resolve) => {
		const timer = setTimeout(resolve, ms);
		if (signal.aborted) {
			clearTimeout(timer);
			resolve();
			return;
		}
		signal.addEventListener(
			"abort",
			() => {
				clearTimeout(timer);
				resolve();
			},
			{ once: true },
		);
	});
}

export default function (pi: ExtensionAPI) {
	let watcher: AbortController | undefined;
	let watchedTrail: TrailInfo | undefined;
	let paused = false;
	const seenCommentIds = new Set<string>();
	const pendingReviewMessages: string[] = [];
	let agentActive = false;
	let reviewMessageInFlight = false;
	let currentTrailLookup: TrailLookup = { status: "none" };
	let watchStatus: "idle" | "watching" | "paused" | "error" = "idle";
	let watchStatusMessage = "";

	function renderEntireTrailsStatus(ui: ExtensionCtx["ui"]) {
		// Clear legacy split footer slots if this file was hot-reloaded from an older version.
		ui.setStatus("trail-link", undefined);
		ui.setStatus("trail-watch", undefined);

		const result = currentTrailLookup;
		if (result.status === "none") {
			ui.setStatus("entire-trails", undefined);
			return;
		}

		if (result.status === "no-trail") {
			ui.setStatus("entire-trails", ui.theme.fg("dim", `No trail for ${result.branch}`));
			return;
		}

		if (result.status === "error") {
			ui.setStatus("entire-trails", ui.theme.fg("dim", formatTrailLookupError(result.message)));
			return;
		}

		const trail = result.trail;
		const trailTitle = trail.title?.trim();
		const label = `Trail #${trail.number}${trailTitle ? ` · ${trailTitle}` : ""}`;
		const hyperlink = `\x1b]8;;${trail.url}\x07${label}\x1b]8;;\x07`;
		let text = ui.theme.fg("accent", hyperlink);
		if (watchStatus === "watching") text += ui.theme.fg("dim", " watching");
		if (watchStatus === "paused") text += ui.theme.fg("dim", " paused");
		if (watchStatus === "error") text += ui.theme.fg("dim", ` error: ${watchStatusMessage}`);
		ui.setStatus("entire-trails", text);
	}

	async function updateEntireTrailsStatus(cwd: string, ui: ExtensionCtx["ui"]) {
		currentTrailLookup = await getTrailForBranch(cwd);
		renderEntireTrailsStatus(ui);
	}

	function stopWatcher() {
		const controller = watcher;
		watcher = undefined;
		watchedTrail = undefined;
		seenCommentIds.clear();
		controller?.abort();
	}

	function sendReviewMessage(message: string, deliverAsFollowUp: boolean): boolean {
		try {
			if (deliverAsFollowUp) pi.sendUserMessage(message, { deliverAs: "followUp" });
			else pi.sendUserMessage(message);
			return true;
		} catch {
			try {
				pi.sendUserMessage(message, { deliverAs: "followUp" });
				return true;
			} catch {
				// Never crash Pi because the watcher failed to inject.
				return false;
			}
		}
	}

	function drainReviewMessageQueue() {
		if (reviewMessageInFlight || pendingReviewMessages.length === 0) return;
		const message = pendingReviewMessages.shift();
		if (!message) return;
		if (sendReviewMessage(message, agentActive)) reviewMessageInFlight = true;
	}

	function enqueueReviewMessage(message: string) {
		pendingReviewMessages.push(message);
		drainReviewMessageQueue();
	}

	async function handleReviewFrame(auth: EntireAuth, trail: TrailInfo, signal: AbortSignal, frame: SSEFrame) {
		if (frame.event !== "comment.created" || !isObject(frame.data)) return;
		const event = frame.data as CodeReviewEvent;
		const commentId = event.target_id;
		if (!commentId || seenCommentIds.has(commentId)) return;
		seenCommentIds.add(commentId);

		const reviewId =
			event.review_id ||
			payloadString(event.payload, "review_id") ||
			event.review_session_id ||
			payloadString(event.payload, "review_session_id");
		const comment = reviewId ? await fetchReviewComment(auth, trail.id, reviewId, commentId, signal) : undefined;
		enqueueReviewMessage(formatReviewComment(trail, event, comment));
	}

	async function runReviewEventWatcher(ctx: ExtensionCtx, trail: TrailInfo, controller: AbortController) {
		let lastEventId = "";
		let cursorInitialized = false;
		let backoff = 500;
		try {
			while (!controller.signal.aborted) {
				try {
					const currentAuth = await getEntireAuth();
					if (!currentAuth) throw new Error('Authentication via "entire auth login" required');

					// Start after the current event log so historical comments are not injected on startup.
					if (!cursorInitialized) {
						lastEventId = await latestEventCursor(currentAuth, trail.eventsPath, controller.signal);
						cursorInitialized = true;
					}

					const headers: Record<string, string> = {
						Accept: "text/event-stream",
						Authorization: `Bearer ${currentAuth.token}`,
					};
					if (lastEventId) headers["Last-Event-ID"] = lastEventId;

					const response = await fetch(apiURL(currentAuth, trail.eventsPath), {
						headers,
						signal: controller.signal,
					});
					if (!response.ok) throw new Error(await responseError(response));

					const reason = await readSSE(response, controller.signal, async (frame) => {
						if (frame.id) lastEventId = frame.id;
						await handleReviewFrame(currentAuth, trail, controller.signal, frame);
					});

					if (controller.signal.aborted || reason === "done") break;
					if (reason === "forbidden") throw new Error("access revoked");
					if (reason === "error") throw new Error("server error");
					if (reason === "reconnect") {
						backoff = 500;
						continue;
					}
				} catch (err) {
					if (controller.signal.aborted) break;
					watchStatus = "error";
					watchStatusMessage = formatTrailLookupError(((err as Error).message || "connection error").split("\n")[0] ?? "connection error");
					renderEntireTrailsStatus(ctx.ui);
					await sleep(backoff, controller.signal);
					backoff = Math.min(backoff * 2, 30000);
				}
			}
		} finally {
			if (watcher === controller) {
				watcher = undefined;
				watchedTrail = undefined;
				seenCommentIds.clear();
				watchStatus = paused ? "paused" : "idle";
				renderEntireTrailsStatus(ctx.ui);
			}
		}
	}

	async function ensureWatcher(
		ctx: ExtensionCtx,
		opts: { notify?: boolean; silentMissing?: boolean; forceRestart?: boolean } = {},
	) {
		if (paused) {
			watchStatus = "paused";
			renderEntireTrailsStatus(ctx.ui);
			return false;
		}

		const result = await getTrailForBranch(ctx.cwd);
		currentTrailLookup = result;
		if (result.status !== "found") {
			stopWatcher();
			watchStatus = "idle";
			renderEntireTrailsStatus(ctx.ui);
			if (!opts.silentMissing) ctx.ui.notify(trailLookupMessage(result), "error");
			return false;
		}

		let auth: EntireAuth | null;
		try {
			auth = await getEntireAuth();
		} catch (err) {
			stopWatcher();
			watchStatus = "error";
			watchStatusMessage = formatTrailLookupError(((err as Error).message || "authentication error").split("\n")[0] ?? "authentication error");
			renderEntireTrailsStatus(ctx.ui);
			return false;
		}
		if (!auth) {
			stopWatcher();
			watchStatus = "error";
			watchStatusMessage = 'Authentication via "entire auth login" required';
			renderEntireTrailsStatus(ctx.ui);
			return false;
		}

		if (!opts.forceRestart && watcher && watchedTrail?.id === result.trail.id) {
			watchStatus = "watching";
			renderEntireTrailsStatus(ctx.ui);
			if (opts.notify) ctx.ui.notify(`Already watching trail #${result.trail.number}.`, "info");
			return true;
		}

		stopWatcher();
		seenCommentIds.clear();

		const controller = new AbortController();
		watcher = controller;
		watchedTrail = result.trail;
		watchStatus = "watching";
		watchStatusMessage = "";
		renderEntireTrailsStatus(ctx.ui);
		if (opts.notify) ctx.ui.notify(`Watching trail #${result.trail.number} review comments.`, "info");
		void runReviewEventWatcher(ctx, result.trail, controller);
		return true;
	}

	pi.registerCommand("trail-watch", {
		description: "Show/control automatic Entire trails review comment watching (pause, resume)",
		handler: async (args: string, ctx: ExtensionCtx) => {
			const action = args.trim().toLowerCase();

			if (action === "pause") {
				paused = true;
				stopWatcher();
				watchStatus = "paused";
				renderEntireTrailsStatus(ctx.ui);
				ctx.ui.notify("Paused trail review watcher. Use /trail-watch resume to turn it back on.", "info");
				return;
			}

			if (action === "resume") {
				paused = false;
				await ensureWatcher(ctx, { notify: true, forceRestart: true });
				return;
			}

			if (action === "") {
				if (paused) {
					ctx.ui.notify("Trail watcher is paused. Use /trail-watch resume to turn it back on.", "info");
					return;
				}
				if (watcher && watchedTrail) {
					ctx.ui.notify(`Watching trail #${watchedTrail.number} review comments. Use /trail-watch pause to pause.`, "info");
					return;
				}
				const result = await getTrailForBranch(ctx.cwd);
				if (result.status === "found") {
					ctx.ui.notify(`Trail watcher is not running for #${result.trail.number}; reload Pi or use /trail-watch resume.`, "info");
					return;
				}
				ctx.ui.notify(trailLookupMessage(result), "info");
				return;
			}

			ctx.ui.notify("Usage: /trail-watch [pause|resume]", "error");
		},
	});

	pi.on("session_start", async (_event, ctx: ExtensionCtx) => {
		await updateEntireTrailsStatus(ctx.cwd, ctx.ui);
		void ensureWatcher(ctx, { silentMissing: true });
	});

	pi.on("agent_start", () => {
		agentActive = true;
	});

	pi.on("agent_end", async (_event, ctx: ExtensionCtx) => {
		reviewMessageInFlight = false;
		if (pendingReviewMessages.length > 0) {
			// Only inject one queued finding per completed agent run. Because this
			// handler runs while the ending run is still settling, use followUp so Pi
			// starts the next review-message turn after the current run is complete.
			agentActive = true;
			drainReviewMessageQueue();
		} else {
			agentActive = false;
		}
		await updateEntireTrailsStatus(ctx.cwd, ctx.ui);
		void ensureWatcher(ctx, { silentMissing: true });
	});

	pi.on("session_shutdown", () => {
		pendingReviewMessages.length = 0;
		reviewMessageInFlight = false;
		agentActive = false;
		stopWatcher();
	});
}

